import {datasets} from './algebra.js';
const rat=n=>Number.isInteger(n)?String(n):`Rational('${n}')`;
const matrix=m=>`Matrix([[${m.slice(0,2).map(rat).join(', ')}], [${m.slice(2).map(rat).join(', ')}]])`;
const vector=v=>`Matrix([${v.map(rat).join(', ')}])`;
const sympy='from sympy import Matrix, Rational, pprint\n\n';
export function pythonFor(id,lesson,s){
 const mode=lesson.lab;
 if(mode==='vectors'||mode==='span')return sympy+`v1 = ${vector(s.u)}\nv2 = ${vector(s.v)}\na, b = ${rat(s.a)}, ${rat(s.b)}\nprint("Linear combination:")\npprint(a*v1 + b*v2)\nA = Matrix.hstack(v1, v2)\nprint("Span dimension:", A.rank())\nprint("Dependence coefficients:", A.nullspace())`;
 if(mode==='transformations'||mode==='determinant')return sympy+`A = ${matrix(s.m)}\n${s.u?`v = ${vector(s.u)}\nprint("A*v:")\npprint(A*v)\n`:''}print("Determinant:", A.det())\nprint("Area scale:", abs(A.det()))\nprint("Rank:", A.rank())`;
 if(mode==='arithmetic')return sympy+`A = ${matrix(s.m)}\nB = ${matrix(s.n)}\nprint("${{ab:'A*B',ba:'B*A',add:'A+B',transpose:'A.T'}[s.operation]}:")\npprint(${{ab:'A*B',ba:'B*A',add:'A+B',transpose:'A.T'}[s.operation]})\nprint("Do these matrices commute?", A*B == B*A)\n# Matrix * is matrix multiplication in SymPy.\n# With NumPy arrays, use @ for matrix multiplication.`;
 if(mode==='elimination')return sympy+`aug = Matrix([${s.rows.map(row=>'['+row.map(n=>`Rational('${n}')`).join(', ')+']').join(', ')}])\nprint("Current augmented matrix:")\npprint(aug)\nreduced, pivots = aug.rref()\nprint("RREF:")\npprint(reduced)\nprint("Pivot column indices (zero-based):", pivots)\n# An augmented-column pivot signals inconsistency.`;
 if(mode==='systems')return sympy+`from sympy import linsolve\nA = ${matrix(s.m)}\nb = ${vector(s.b)}\nprint("Solution set:")\npprint(linsolve((A, b)))\nprint("Coefficient rank:", A.rank())\nprint("Augmented rank:", A.row_join(b).rank())\n# EmptySet means no solution; free symbols parameterize a family.`;
 if(mode==='closure')return sympy+`a, b, c = ${rat(s.a)}, ${rat(s.b)}, ${rat(s.c)}\nfamily = '${s.family}'\ndef y(x):\n    return x if family == 'line' else x+1 if family == 'offset' else x*x\ndef inside(point):\n    return point[1] == y(point[0])\nu, v = Matrix([a, y(a)]), Matrix([b, y(b)])\nprint("Zero is inside:", inside(Matrix([0, 0])))\nprint("u + v is inside:", inside(u + v))\nprint("c*u is inside:", inside(c*u))\n# These samples illustrate closure; a general proof needs arbitrary values.`;
 if(mode==='coordinates')return sympy+`from sympy import linsolve\nu, v, w = ${vector(s.u)}, ${vector(s.v)}, ${vector(s.w)}\nB = Matrix.hstack(u, v)\nprint("Coordinates solving B*c = w:")\npprint(linsolve((B, w)))\nprint("Pair rank:", B.rank())\nprint("Relationships among u, v, w:")\npprint(Matrix.hstack(u, v, w).nullspace())\n# A nullspace vector gives coefficients, not original vectors.`;
 if(mode==='matrixspace'){
  const family=s.family,form=family==='symmetric'?'Matrix([[a,b],[b,c]])':family==='skew'?'Matrix([[0,-a],[a,0]])':'Matrix([[a,b],[c,-a]])';
  const basis=family==='symmetric'?'[Matrix([[1,0],[0,0]]), Matrix([[0,1],[1,0]]), Matrix([[0,0],[0,1]])]':family==='skew'?'[Matrix([[0,-1],[1,0]])]':'[Matrix([[1,0],[0,-1]]), Matrix([[0,1],[0,0]]), Matrix([[0,0],[1,0]])]';
  return sympy+`a, b, c = ${rat(s.a)}, ${rat(s.b)}, ${rat(s.c)}\nA = ${form}\nbasis = ${basis}\npprint(A)\nflattened = Matrix.hstack(*[B.reshape(4, 1) for B in basis])\nprint("Space dimension:", flattened.rank())\nprint("Trace:", A.trace())\nprint("Symmetric:", A.T == A)\nprint("Skew-symmetric:", A.T == -A)`;
 }
 if(mode==='homogeneous')return sympy+`A = ${matrix(s.m)}\nt, z = ${rat(s.t)}, ${rat(s.z)}\nprint("Null-space basis:")\npprint(A.nullspace())\nif A.rank() == 0:\n    x = Matrix([t, z])\nelif A.rank() == 2:\n    x = Matrix([0, 0])\nelse:\n    row = max([A.row(0), A.row(1)], key=lambda r: r.norm())\n    direction = Matrix([-row[1], row[0]])\n    x = t * direction / direction.norm()\nprint("Displayed solution:")\npprint(x)\nprint("A*x:")\npprint(A*x)\nprint("Rank + nullity:", A.rank() + len(A.nullspace()))`;
 if(mode==='nullspace')return sympy+`A = ${matrix(s.m)}\nx = ${vector(s.u)}\nprint("A*x:")\npprint(A*x)\nprint("Null-space basis (input space):")\npprint(A.nullspace())\nprint("Column-space basis (output space):")\npprint(A.columnspace())\nprint("Row-space basis:")\npprint(A.rowspace())\nprint("Rank + nullity:", A.rank(), "+", len(A.nullspace()), "=", A.cols)`;
 if(mode==='orthogonal'||mode==='projection')return sympy+`u, v = ${vector(s.u)}, ${vector(s.v)}\nprint("Dot product:", u.dot(v))\nprint("Norms:", u.norm(), v.norm())\np = (u.dot(v)/v.dot(v))*v if v.dot(v) != 0 else Matrix([0, 0])\nr = u - p\nprint("Projection:")\npprint(p)\nprint("Residual:")\npprint(r)\nprint("Residual dot direction:", r.dot(v))\nprint("Distance:", r.norm())`;
 if(mode==='eigen')return sympy+`from sympy import cos, sin, pi\nA = ${matrix(s.m)}\nangle = Rational('${s.angle}') * pi / 180\nv = 2*Matrix([cos(angle), sin(angle)])\nprint("Eigenvalue, multiplicity, eigenvector basis:")\npprint(A.eigenvects())\nprint("Candidate image (numerical):")\npprint((A*v).evalf(5))\nprint("The zero vector is excluded from eigenvector bases.")`;
 if(mode==='decomposition'){
  const code={qr:`Q, R = A.QRdecomposition()\n# SymPy may use reduced factors when A is rank-deficient.\nprint("Q:"); pprint(Q)\nprint("R:"); pprint(R)\nprint("A == Q*R:", A == Q*R)`,lu:`L, U, swaps = A.LUdecomposition()\nP = Matrix.eye(A.rows)\nfor i, j in swaps:\n    P.row_swap(i, j)\nprint("P:"); pprint(P)\nprint("L:"); pprint(L)\nprint("U:"); pprint(U)\nprint("P*A == L*U:", P*A == L*U)`,cholesky:`try:\n    L = A.cholesky()\n    pprint(L)\n    print("A == L*L.T:", A == L*L.T)\nexcept Exception as error:\n    print("Cholesky requires a symmetric positive-definite input:", error)`,eigen:`try:\n    P, D = A.diagonalize(reals_only=True)\n    print("P:"); pprint(P)\n    print("D:"); pprint(D)\n    print("A == P*D*P.inv():", A == P*D*P.inv())\nexcept Exception as error:\n    print("No real eigenbasis:", error)`};
  return sympy+`A = ${matrix(s.m)}\n`+code[s.method];
 }
 if(mode==='svd')return `import numpy as np\n\nA = np.array(${JSON.stringify([s.m.slice(0,2),s.m.slice(2)])}, dtype=float)\nk = ${s.k}\nU, s, Vh = np.linalg.svd(A, full_matrices=False)\nA_k = U[:, :k] @ np.diag(s[:k]) @ Vh[:k, :]\nprint("Singular values:", s)\nprint("Rank-limited reconstruction:", A_k)\nprint("Frobenius error:", np.linalg.norm(A - A_k, 'fro'))\nprint("Full reconstruction:", np.allclose(A, U @ np.diag(s) @ Vh))\n# Vh is already the transpose of V for real inputs.`;
 if(mode==='regression')return `import numpy as np\n\nx = np.array([-2, -1, 0, 1, 2], dtype=float)\ny = np.array(${JSON.stringify(s.ys)}, dtype=float)\nA = np.column_stack((x, np.ones_like(x)))\ncoeff, _, rank, singular_values = np.linalg.lstsq(A, y, rcond=None)\nprint("Best slope and intercept:", coeff)\nprint("Minimum squared error:", np.linalg.norm(y - A @ coeff)**2)\ncurrent = np.array([${s.slope}, ${s.intercept}])\nprint("Your squared error:", np.linalg.norm(y - A @ current)**2)\nprint("Residual orthogonal to columns:", np.allclose(A.T @ (y - A @ coeff), 0))`;
 if(mode==='pca')return `import numpy as np\n\nraw = np.array(${JSON.stringify(datasets[s.dataset])}, dtype=float)\ncenter = ${s.center?'True':'False'}\nX = raw - raw.mean(axis=0) if center else raw.copy()\nU, s, Vh = np.linalg.svd(X, full_matrices=False)\nk = ${s.k}\nreconstruction = (X @ Vh[:k, :].T) @ Vh[:k, :]\nprint("Principal directions (rows):", Vh)\nprint("${s.center?'Explained variance':'Uncentered energy'} ratios:", s**2 / (s**2).sum() if (s**2).sum() else "undefined")\nprint("Reconstruction error:", np.linalg.norm(X - reconstruction, 'fro'))\nangle = np.deg2rad(${s.angle})\nw = np.array([np.cos(angle), np.sin(angle)])\nprint("Candidate 1D retained share:", np.linalg.norm(X @ w)**2 / np.linalg.norm(X)**2 if np.linalg.norm(X) else "undefined")\n# Add raw.mean(axis=0) back after a centered reconstruction.\n# Uncentered energy ratios are not explained-variance ratios.`;
 throw new Error('No Python example for '+mode);
}
